import { PsychScale, ScaleCategory } from '../types';

export type CompactScaleTuple = [
  id: string,
  acronym: string,
  name: string,
  authors: string,
  year: number,
  category: ScaleCategory,
  itemCount: number,
  description: string,
  likertMin: number,
  likertMax: number,
  likertLabels: string[],
  sampleItems: { number: number; text: string; reverse?: boolean }[],
  reliability: string,
  validity: string,
  scoringGuide: string,
  citationApa7: string
];

export const mapCompactScales = (rows: CompactScaleTuple[]): PsychScale[] =>
  rows.map(
    ([
      id,
      acronym,
      name,
      authors,
      year,
      category,
      itemCount,
      description,
      likertMin,
      likertMax,
      likertLabels,
      sampleItems,
      reliability,
      validity,
      scoringGuide,
      citationApa7
    ]) => ({
      id,
      acronym,
      name,
      authors,
      year,
      category,
      itemCount,
      description,
      likertMin,
      likertMax,
      likertLabels,
      sampleItems,
      reliability,
      validity,
      scoringGuide,
      citationApa7
    })
  );

